/// <summary>
/// Interface for blocks containing data collection logic when further data needs to be picked before posting. This ensures that the block can provide header fields, optional flow steps, a posting method, a prompt for additional steps from the posting,
/// </summary>
interface TFMLogicBlockPrePostDataCollectionInterface
{
}

